//! Canonical-bytes cases: JCS canonical JSON, base64url, challenge-id HMAC,
//! x402 envelope wire bytes. All generated by the kit's own encoders.

use serde_json::{json, Value};

use crate::case::{
    spec, BugType, Case, CaseBuilder, Expect, Input, Intent, Mode, Pin, Role, SpecRef, Suite,
};

const MPP_CHARGE: &str = "mpp-specs/specs/methods/solana/draft-solana-charge-00.md";
const MPP_CORE: &str = "mpp-specs/specs/core/draft-httpauth-payment-01.md";

/// MPP-51806e831a: JCS before encoding. MPP-71198689c1: base64url, no
/// padding. MPP-f4eca94243: never append padding.
const JCS: &str = "MPP-51806e831a";
const B64URL: &str = "MPP-71198689c1";
const NO_PAD: &str = "MPP-f4eca94243";
/// MPP-8a3cdc949b: the challenge id binds realm, method, intent, request,
/// expires, digest, opaque.
const ID_BINDING: &str = "MPP-8a3cdc949b";

fn jcs_spec() -> SpecRef {
    spec(
        MPP_CHARGE,
        "Encoding Conventions",
        "All JSON {{RFC8259}} objects carried in auth-params or HTTP headers in this specification MUST be serialized using the JSON Canonicalization Scheme (JCS) {{RFC8785}} before encoding.",
    )
}

fn b64_spec() -> SpecRef {
    spec(
        MPP_CHARGE,
        "Encoding Conventions",
        "The resulting bytes MUST then be encoded using base64url {{RFC4648}} Section 5 without padding characters (=).",
    )
}

fn id_spec() -> SpecRef {
    spec(
        MPP_CORE,
        "Challenge Binding",
        "Servers MUST bind the challenge id to realm, method, intent, and request, and to expires, digest, opaque, and header when present.",
    )
}

fn bytes_case(
    id: &str,
    file: &'static str,
    spec: SpecRef,
    reqs: &[&str],
    description: &str,
    input: Value,
    pin: &[&'static str],
) -> Case {
    CaseBuilder::new(
        id,
        file,
        Suite::CanonicalBytes,
        Intent::Charge,
        Mode::CanonicalBytes,
        Role::Both,
        BugType::Wire,
        spec,
        description,
        Input::Static(input),
        Expect::Accept(Pin::ExactBytes(pin.to_vec())),
    )
    .requirements(reqs)
    .build()
}

fn challenge_id(extra: Value) -> Value {
    let mut cid = json!({
        "secretKey": "test-secret-key",
        "realm": "https://api.example.com",
        "method": "GET",
        "intent": "charge",
        "request": "eyJhbW91bnQiOiIxMDAwMDAwIn0",
    });
    if let Value::Object(extra) = extra {
        for (k, v) in extra {
            cid[k] = v;
        }
    }
    json!({ "challengeId": cid })
}

fn x402_accepts() -> Value {
    json!({
        "scheme": "exact",
        "network": "solana:EtWTRABZaYq6iMfeYKouRu166VU2xqa1",
        "amount": "1000000",
        "asset": "4zMMC9srt5Ri5X14GAgXhaHii3GnPAEERYPJgZJDncDU",
        "payTo": "3yQ3Y8Z1n3wKXa1234567890abcdefghijkLMNopqrs",
        "maxTimeoutSeconds": 300
    })
}

crate::registry! {
    canonical_json_nested_key_order => bytes_case(
        "canonical-json-nested-key-order",
        "canonical-bytes.json",
        jcs_spec(),
        &[JCS, B64URL],
        "Divergence class: canonical JSON (RFC 8785 JCS). Object keys must sort by UTF-16 code unit at every nesting level. Pins exact canonical JSON and its base64url.",
        json!({ "value": { "b": 2, "a": [{ "b": true, "a": false }] } }),
        &["canonicalJson", "base64Url"],
    );
    canonical_bytes_48_base64url => bytes_case(
        "canonical-bytes-48-base64url",
        "canonical-bytes.json",
        b64_spec(),
        &[B64URL, NO_PAD],
        "Divergence class: 48-byte / base64url encoding. A fixed 48-byte sequence (0x00..0x2f) must base64url-encode identically across SDKs (no padding, URL-safe alphabet).",
        json!({ "encodeBase64Url": { "hexBytes": "000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f202122232425262728292a2b2c2d2e2f" } }),
        &["bytes", "base64Url"],
    );
    canonical_bytes_utf8_base64url => bytes_case(
        "canonical-bytes-utf8-base64url",
        "canonical-bytes.json",
        b64_spec(),
        &[B64URL, NO_PAD],
        "Divergence class: base64url of a UTF-8 string. Pins the URL-safe, unpadded base64url of an ASCII label so every SDK's base64url helper agrees.",
        json!({ "encodeBase64Url": { "utf8": "mpp-conformance" } }),
        &["base64Url"],
    );
    challenge_id_hmac_required_only => bytes_case(
        "challenge-id-hmac-required-only",
        "wire-bytes.json",
        id_spec(),
        &[ID_BINDING],
        "Divergence class: MPP charge challenge-id HMAC derivation. base64url(HMAC-SHA256(secret, realm|method|intent|request|expires|digest|opaque)) with absent optionals joined as empty strings. Required-only inputs (no expires/digest/opaque). Mirrors rust compute_challenge_id (protocol/core/challenge.rs). Pins cross-SDK challenge-id agreement byte-for-byte so two SDKs computing a different id from the same inputs are caught here, not behind a live-server roundtrip.",
        challenge_id(json!({})),
        &["base64Url"],
    );
    challenge_id_hmac_with_expires => bytes_case(
        "challenge-id-hmac-with-expires",
        "wire-bytes.json",
        id_spec(),
        &[ID_BINDING],
        "Challenge-id HMAC with an RFC 3339 expires segment. The expires string is an RFC 3339 / ISO 8601 UTC timestamp (battle-tested format) and must enter the HMAC input verbatim, changing the id relative to required-only.",
        challenge_id(json!({ "expires": "2026-01-01T00:00:00Z" })),
        &["base64Url"],
    );
    challenge_id_hmac_with_digest => bytes_case(
        "challenge-id-hmac-with-digest",
        "wire-bytes.json",
        id_spec(),
        &[ID_BINDING],
        "Challenge-id HMAC with a digest segment (RFC 9530 Repr-Digest SFV value sha-256=:...:). The digest binds the request body hash into the id; it must enter the HMAC input verbatim.",
        challenge_id(json!({ "digest": "sha-256=:abc123:" })),
        &["base64Url"],
    );
    challenge_id_hmac_with_opaque => bytes_case(
        "challenge-id-hmac-with-opaque",
        "wire-bytes.json",
        id_spec(),
        &[ID_BINDING],
        "Challenge-id HMAC with an opaque segment. opaque is server-issued nonce material; it must enter the HMAC input verbatim.",
        challenge_id(json!({ "opaque": "opaque-token-xyz" })),
        &["base64Url"],
    );
    challenge_id_hmac_all_fields => bytes_case(
        "challenge-id-hmac-all-fields",
        "wire-bytes.json",
        id_spec(),
        &[ID_BINDING],
        "Challenge-id HMAC with every optional present (expires + digest + opaque). Pins the fully-bound id so an SDK that drops or reorders any segment diverges here.",
        challenge_id(json!({ "expires": "2026-01-01T00:00:00Z", "digest": "sha-256=:abc123:", "opaque": "opaque-token-xyz" })),
        &["base64Url"],
    );
    x402_payment_signature_envelope_canonical_wire => bytes_case(
        "x402-payment-signature-envelope-canonical-wire",
        "wire-bytes.json",
        jcs_spec(),
        &[JCS, B64URL],
        "Divergence class: x402 v2 PAYMENT-SIGNATURE payment envelope wire bytes. The envelope object {x402Version, accepted, payload} is canonicalized via RFC 8785 JCS and base64url-encoded; the canonical accepted object carries scheme/network/amount/asset/payTo/maxTimeoutSeconds(=300 default). Pins the exact wire string so an SDK that quotes a parameter differently, reorders fields, or base64url-pads the embedded payload breaks here instead of silently passing the on-chain settlement oracle. (The optional `extra` map is omitted here: an empty `{}` is indistinguishable from `[]` once decoded into a dynamically-typed runner's untyped container, so the empty-map encoding is a separate concern from envelope wire agreement.)",
        json!({ "value": { "x402Version": 2, "accepted": x402_accepts(), "payload": { "transaction": "AA==" } } }),
        &["canonicalJson", "base64Url"],
    );
    x402_payment_required_envelope_canonical_wire => bytes_case(
        "x402-payment-required-envelope-canonical-wire",
        "wire-bytes.json",
        jcs_spec(),
        &[JCS, B64URL],
        "Divergence class: x402 PAYMENT-REQUIRED challenge envelope wire bytes. The 402 challenge body {x402Version, accepts:[...], error} is canonicalized via RFC 8785 JCS and base64url-encoded. accepts carries the same canonical PaymentRequirements as the accepted echo. Pins the exact challenge-envelope wire string across SDKs. (The optional `extra` map is omitted, same rationale as the PAYMENT-SIGNATURE vector.)",
        json!({ "value": { "x402Version": 2, "accepts": [x402_accepts()], "error": "payment required" } }),
        &["canonicalJson", "base64Url"],
    );
}
